export function createExecutionItem(data = {}) { return { id: "", userId: "", type: "commitment", title: "", description: "", cadence: { type: "daily" }, preferredSchedule: {}, active: true, linkedStrategyIds: [], linkedGoalIds: [], linkedEvidenceTypes: [], completionMethod: "manual", reminderPreference: "in_app", notes: "", author: { type: "user", id: "", displayName: "Founder" }, createdAt: null, updatedAt: null, ...data }; }
export function validateExecutionItem(item = {}) { const errors=[]; if(!item.id)errors.push("Execution id is required.");if(!item.userId)errors.push("User is required.");if(!item.title)errors.push("Title is required.");if(!["daily","weekly","scheduled_date","specific_weekdays","custom"].includes(item.cadence?.type))errors.push("Choose a supported cadence.");return{valid:!errors.length,errors}; }
