export function createExecutionItemRepository(items=[],options={}){return{async listExecutionItems(userId){return structuredClone(items.filter(x=>x.userId===userId));},async getExecutionItemById(id){return structuredClone(items.find(x=>x.id===id)??null);},async saveExecutionItem(item){const i=items.findIndex(x=>x.id===item.id);if(i>=0)items[i]=structuredClone(item);else items.push(structuredClone(item));options.onChange?.();return structuredClone(item);}}}
